using Ergonomy;
int passed = 0;
void Check(bool ok, string name) { if (!ok) throw new Exception("FAIL: " + name); Console.WriteLine("PASS: " + name); passed++; }
void Run(WellnessSchedule s, int seconds, bool idle=false, bool quiet=false) {for(int i=0;i<seconds;i++) s.Advance(1,idle,quiet);}
var defaults = new AppSettings();
Check(defaults.EyeMinutes==20 && defaults.PostureMinutes==30 && defaults.MoveMinutes==55 && !defaults.WaterEnabled && !defaults.AutoStart,"scientific product defaults and optional startup");
var s = new WellnessSchedule(defaults);
Run(s,1199); Check(s.Pending==null,"no early eye reminder");
s.Advance(1,false,false); Check(s.Pending==ReminderKind.Eye,"eye due at 1200 active seconds");
Run(s,100); Check(s.Pending==ReminderKind.Eye,"single pending reminder");
s.Respond(ReminderKind.Eye,ReminderResponse.Done); Check(s.Pending==null && s.Next!.Value.Remaining.TotalSeconds>0,"Done clears pending");
var idleSchedule=new WellnessSchedule(defaults); Run(idleSchedule,3600,idle:true); Check(idleSchedule.ActiveSeconds==0 && idleSchedule.Pending==null,"idle and lock do not charge work");
idleSchedule.Advance(7200,false,false); Check(idleSchedule.ActiveSeconds==0,"sleep gap does not charge work");
var quietSchedule=new WellnessSchedule(defaults); Run(quietSchedule,1300,quiet:true); Check(quietSchedule.Pending==null,"fullscreen suppresses delivery while counting active work");
quietSchedule.Advance(1,false,false); Check(quietSchedule.Pending==ReminderKind.Eye,"quiet exit delivers one overdue reminder");
quietSchedule.Respond(ReminderKind.Eye,ReminderResponse.Done); Run(quietSchedule,88); Check(quietSchedule.Pending==null,"cooldown prevents catch-up burst");
var snooze = new WellnessSchedule(new(){EyeMinutes=1,PostureEnabled=false,MoveEnabled=false}); Run(snooze,60); snooze.Respond(ReminderKind.Eye,ReminderResponse.Snooze); Run(snooze,599); Check(snooze.Pending==null,"snooze holds target 10 minutes"); snooze.Advance(1,false,false); Check(snooze.Pending==ReminderKind.Eye,"snooze reoffers target");
var practice=new WellnessSchedule(defaults);Run(practice,1199);practice.Respond(ReminderKind.Eye,ReminderResponse.Done,practice:true);practice.Advance(1,false,false);Check(practice.Pending==ReminderKind.Eye,"manual practice does not reset automatic schedule");
var pause=new WellnessSchedule(defaults);pause.PauseFor(TimeSpan.FromSeconds(120));Run(pause,119);Check(pause.ActiveSeconds==0,"manual pause freezes work");pause.Resume();pause.Advance(1,false,false);Check(pause.ActiveSeconds==1,"manual resume continues");
var disabled=new WellnessSchedule(new(){EyeEnabled=false,PostureEnabled=false,MoveEnabled=false});Run(disabled,10000);Check(disabled.Next==null && disabled.Pending==null,"all reminders disabled");
var hydration=new WellnessSchedule(new(){EyeEnabled=false,PostureEnabled=false,MoveEnabled=false,WaterEnabled=true});Run(hydration,7200);Check(hydration.Pending==ReminderKind.Water,"optional hydration at 120 active minutes");
var corner=new CornerReveal();
Check(!corner.Revealed,"corner is fully concealed by default");
Check(!corner.Update(.2,true,false,false,false),"hover dwell avoids accidental reveal");
Check(corner.Update(.2,true,false,false,false),"right-edge hover reveals");
for(int i=0;i<4;i++)corner.Update(.2,false,false,false,false);
Check(corner.Revealed,"leave grace avoids jitter during slide");
for(int i=0;i<3;i++)corner.Update(.2,false,false,false,false);
Check(!corner.Revealed,"corner retreats after pointer leaves");
Check(corner.Update(.2,false,false,true,false),"automatic reminder reveals without pointer");
Check(!corner.Update(.2,true,true,true,true),"quiet mode overrides reminder and hover");
var eye=new ExerciseLesson(ReminderKind.Eye){Running=true};
for(int i=0;i<5;i++)eye.Advance(1);
Check(eye.Index==0 && eye.StepComplete && !eye.Running,"finished step waits for explicit Next");
eye.Advance(2);Check(eye.Index==0,"time alone never changes the movement");
Check(eye.Next() && eye.Index==1 && eye.Remaining==20,"Next starts a full independent far-focus timer");
eye.Running=false;eye.Advance(2);Check(eye.Remaining==20,"lesson pause freezes countdown");
eye.Running=true;eye.Advance(300);Check(eye.Remaining==20,"suspend gap does not complete exercise");
for(int i=0;i<20;i++)eye.Advance(1);
Check(eye.Finished&&!eye.Running,"exercise ends without automatic Done response");
Check(new ExerciseLesson(ReminderKind.Posture).Steps.Count==3 && new ExerciseLesson(ReminderKind.Move).Steps.Count==4,"body coaching has explicit staged motion");
Check(!eye.Next(),"cannot advance beyond last movement");
Check(eye.Previous() && eye.Index==0 && eye.Remaining==5 && eye.Running,"Previous resets selected timer");
Check(!eye.Previous(),"cannot move before first movement");
eye.Advance(2);eye.Restart();Check(eye.Remaining==5 && eye.Running,"repeat restarts just the current movement");
Check(!SideDockGeometry.IsHotspot(1919,1,1920,0,1040,1),"window close corner never triggers reveal");
Check(SideDockGeometry.IsHotspot(1919,90,1920,0,1040,1),"right edge activation below title bar");
Check(!SideDockGeometry.IsHotspot(1850,90,1920,0,1040,1),"activation is confined to edge strip");
Check(SideDockGeometry.IsHotspot(2879,135,2880,0,1560,1.5),"edge activation scales with DPI");
Check(!SideDockGeometry.IsHotspot(2879,40,2880,0,1560,1.5),"high-DPI caption controls remain excluded");
Check(SideDockGeometry.Offset(1040,1)==64,"dock raised to 64 DIP below title-bar controls");
Check(ExerciseCatalog.All.Count==20 && ExerciseCatalog.All.Select(x=>x.Motion).Distinct().Count()==20,"twenty named motion and water entries");
Check(ExerciseCatalog.All.All(x=>x.Seconds>0&&!string.IsNullOrWhiteSpace(x.Title)&&!string.IsNullOrWhiteSpace(x.Hint)),"all exercises have Persian text and individual timers");
Check(ExerciseCatalog.All.Where(x=>x.Motion!=ExerciseMotion.Water).All(x=>Uri.TryCreate(x.Source,UriKind.Absolute,out var u)&&u.Scheme=="https"),"all exercise entries retain primary-source links");
Check(SettingsValidation.Minutes("۲۵")==25 && SettingsValidation.Minutes("٣٠")==30,"Persian and Arabic digits parse");
bool rejected=false;try{SettingsValidation.Minutes("۰");}catch(ArgumentException){rejected=true;}Check(rejected,"zero interval rejected");
var custom=new CustomReminder{Title="استراحت دست",Message="دست‌ها را رها کن",Minutes=1};
var userSettings=new AppSettings{EyeEnabled=false,PostureEnabled=false,MoveEnabled=false,CustomReminders=[custom]};
var userSchedule=new WellnessSchedule(userSettings);Run(userSchedule,59);Check(userSchedule.Pending==null,"custom reminder never fires early");
userSchedule.Advance(1,false,false);Check(userSchedule.Pending==ReminderKind.Custom&&userSchedule.PendingCustom?.Id==custom.Id,"custom reminder dispatches correct identity");
userSchedule.Respond(ReminderKind.Custom,ReminderResponse.Snooze);Run(userSchedule,599);Check(userSchedule.Pending==null,"custom snooze holds exact target");userSchedule.Advance(1,false,false);Check(userSchedule.Pending==ReminderKind.Custom,"custom snooze returns target");
userSchedule.Respond(ReminderKind.Custom,ReminderResponse.Done);custom.Enabled=false;userSchedule.Settings=userSettings;Run(userSchedule,500);Check(userSchedule.Pending==null&&userSchedule.Next==null,"disabled personal reminder stays silent");
var added=new CustomReminder{Title="کار بعدی",Minutes=1};userSettings.CustomReminders.Add(added);userSchedule.Settings=userSettings;Run(userSchedule,59);Check(userSchedule.Pending==null,"new custom interval starts at configuration time");userSchedule.Advance(1,false,false);Check(userSchedule.PendingCustom?.Id==added.Id,"new custom becomes due after its own interval");
userSettings.CustomReminders.Remove(added);userSchedule.Settings=userSettings;Check(userSchedule.Pending==null,"deleting pending custom clears scheduler slot");
var a=new CustomReminder{Title="اول",Minutes=1};var b=new CustomReminder{Title="دوم",Minutes=1};
var fair=new WellnessSchedule(new(){EyeEnabled=false,PostureEnabled=false,MoveEnabled=false,CustomReminders=[a,b]});Run(fair,60);fair.Respond(ReminderKind.Custom,ReminderResponse.Done);Run(fair,89);Check(fair.Pending==null,"personal reminders share anti-burst cooldown");fair.Advance(1,false,false);Check(fair.PendingCustom?.Id==b.Id,"oldest due reminder prevents starvation");
var invalid=new AppSettings{CustomReminders=[new(){Id="bad",Title="  کار  ",Minutes=-7}]};SettingsValidation.Normalize(invalid);Check(invalid.CustomReminders[0].Minutes==1&&Guid.TryParse(invalid.CustomReminders[0].Id,out _),"malformed personal settings recover safely");
var roundTrip=System.Text.Json.JsonSerializer.Deserialize<AppSettings>(System.Text.Json.JsonSerializer.Serialize(userSettings));Check(roundTrip!.CustomReminders[0].Message==custom.Message,"personal settings survive JSON round trip");
Console.WriteLine($"{passed} behavioral assertions passed.");
